class APIKeyBase(SecurityBase):
    not_authenticated_status_code: Optional[int] = None

    @staticmethod
    def check_api_key(api_key: Optional[str], auto_error: bool) -> Optional[str]:
        if not api_key:
            if auto_error:
                status_code = APIKeyBase.not_authenticated_status_code if APIKeyBase.not_authenticated_status_code is not None else HTTP_403_FORBIDDEN
                raise HTTPException(
                    status_code=status_code, detail="Not authenticated"
                )
            return None
        return api_key

